"""Kinds."""


class Box:
    """A box."""

    def __init__(self, items):
        """Hold the items."""
        self.items = items

    def __repr__(self):
        """Show the box."""
        return f"Box({self.items!r})"

    @property
    def _size(self):
        """The item count."""
        return len(self.items)

    def count(self):
        """Count the items."""
        return self._size


class Source:
    """A source."""

    def read(self):
        """Read through the subclass."""
        return self._fetch()

    def _fetch(self):
        """Fetch nothing."""
        rows = []
        return rows


class FileSource(Source):
    """A file source."""

    def _fetch(self):
        """Fetch one row."""
        rows = ["row"]
        return rows
